export function createPluncApp(name, id, configuration, registry, library) {
    let ready = false;
    let onReadyLtns = [];
    return {
        name,
        id,
        config: configuration,
        registry,
        library,
        onReadyLtns,
        toReady: () => {
            ready = true;
        },
        isReady: () => ready,
        onReady: (listener) => {
            onReadyLtns.push(listener);
        },
    };
}
